  --core-font-weight-price-grid: 600;


  --btn-color: #f4993d;
  --btn-hover-color: #e78534;
  --btn-text-color: #ffffff;
  --button-font-size: ;
  --button-font-style: uppercase;
  --button-weight: ;
  --collection-height: 200;
  --collection-list-item-heading-line-height: ;
  --color-divider: ;




  --link-color: #df6518;
  --link-hover-color: #07a5d2;


  --pf-primary-font: var(--core-theme-font-family);

  --rating-value: ;
  --shop-bg-color: #ffffff;

}
html,
body,
div.__pf,
button,
input,
select,
textarea,
label {
  --pf-primary-font: var(--core-theme-font-family) !important;
  --pf-secondary-font: var(--core-theme-font-family) !important;
  --regular--fon: var(--core-theme-font-family) !important;
  font-family: var(--core-theme-font-family);
}

body *:where(:not(svg[class*="tee-"] *)),body *:before,body *:after{
  font-family:inherit
}

