/* Rooot */

.uid-product-content-wrapper {
    margin-top: 50px;
}
.uid-product-content-container {
    display: flex;
    flex-direction: column;
    gap: 35px;
}

.uid-product-content-heading {
    text-align: center;
    font-size: 28px;
    font-weight: 600;
    line-height: 1;
    color: var(--core-text-primary);
    text-transform: capitalize;
}

.uid-product-content-title {
    font-size: 20px;
    width: 100%;
    height: auto;
    font-weight: 600;
    line-height: 1.4;
}
.uid-product-content-desc {
    font-size: 16px;
    width: 100%;
    height: auto;
    margin: 0;
    font-weight: 400;
    line-height: 1.5;
    color: var(--core-text-primary);
}

.image-placeholder,
.uid-product-content-image-source {
    display: flex;
    width: 100%;
}

.image-placeholder {
    aspect-ratio: 1/1;
}

.image-placeholder,
.uid-product-content-image-source img {
    display: flex;
    height: 100%;
    width: 100%;
    object-fit: cover;
    object-position: center center;
}

/* Banner  */
.uid-product-content__banner {
    border-radius: 20px;
    overflow: hidden;
}

/* Benefits  */
.uid-product-content__benefits {
    --layout-max-width: 1150px;
    --layout-padding-left-right: 20px;
}

.uid-product-content__benefits {
    max-width: var(--layout-max-width);
    margin: 0 auto;
    padding: 0 var(--layout-padding-left-right);
}

.uid-product-content__benefits .uid-benefits__cols-wrapper {
    --gap: 20px;
    --columns: 3;
}

.uid-product-content__benefits .uid-benefits__cols-wrapper {
    display: flex;
    flex-direction: row;
    gap: var(--gap);
    flex-wrap: wrap;
}

.uid-product-content__benefits .uid-benefits__content {
    max-width: calc((100% - var(--gap) * (min(var(--columns), var(--item-number)) - 1)) / min(var(--columns), var(--item-number)));
    border-radius: 20px;
    overflow: hidden;
    background-color: #fafafa;
    border: 1px solid #eaeaea;
    padding-bottom: 15px;
    width: 100%;
}

.uid-product-content__benefits .uid-product-content-heading {
    margin-bottom: 10px;
}

.uid-product-content__benefits .uid-product-content-title,
.uid-occasions__content-paragh .uid-product-content-title {
    text-align: center;
    margin: 10px 0 5px 0;
}

.uid-benefits__content-paragh .uid-product-content-desc {
    padding: 0 10px;
}
.uid-product-content__benefits .uid-product-content-desc,
.uid-occasions__content-paragh .uid-product-content-desc {
    text-align: center;
}


/* Details  */
.uid-product-content__details {
    max-width: 1050px;
    margin: 0 auto;
    display: flex;
    row-gap: 25px;
    column-gap: 30px;
}

.uid-product-content__details .uid-details-image {
    flex: 25%;
    border-radius: 20px;
    overflow: hidden;
}

.uid-product-content__details .uid-details-image .uid-product-content-image-source {
    height: 100%;
}

.uid-product-content__details .uid-details-image img {
    aspect-ratio: auto;
    display: flex;
    height: 100%;
    width: 100%;
    object-fit: cover;
    object-position: center center;
}

.uid-product-content__details .uid-details-image video {
    aspect-ratio: 1 / 1;
    display: flex;
    height: auto;
    width: 100%;
    object-fit: cover;
    object-position: center center;
}

.uid-product-content__details .uid-details-content {
    display: flex;
    flex-direction: column;
    gap: 15px;
    flex: 30%;
    justify-content: space-between;
}

.uid-product-content__details .uid-details-content-item {
    --gap-details: 20px;
    display: flex;
    flex-direction: row;
    gap: var(--gap-details);
    width: 100%;
    align-items: center;
    min-height: 115px;
}

.uid-details-content-item .uid-details-content-image {
    width: 30%;
    border-radius: 100%;
    overflow: hidden;
    border: 2px solid var(--core-text-primary);
}

.uid-details-content-paragh,
.uid-good-to-know__content-paragh {
    display: flex;
    flex-direction: column;
    gap: 4px;
    width: 100%;
}


/* Occasions  */

.uid-product-occasions {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.uid-product-occasions .uid-occasions-media {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    column-gap: 20px;
    row-gap: 15px;
}

.uid-product-occasions .uid-occasions-video,
.uid-product-occasions .uid-occasions-image {
    width: calc((100% - 20px * (min(2, var(--item-number)) - 1)) / min(2, var(--item-number)));
    border-radius: 20px;
    overflow: hidden;
}

.uid-product-occasions .uid-occasions-media video {
    width: 100%;
    display: flex;
}

.uid-product-occasions .uid-occasions-items {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 20px;
}

.uid-product-occasions .uid-occasions__content {
    width: calc((100% - 20px * (min(4, var(--item-number)) - 1)) / min(4, var(--item-number)));
    background-color: #fffdf8;
    border: 1px solid #e49b15;
    padding: 15px 15px 20px 15px;
    border-radius: 20px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.uid-product-occasions .uid-occasions__content-image {
    width: 25%;
}



/* Good to know  */


.uid-product-good-to-know {
    padding-left: 20px;
}

.uid-product-good-to-know .uid-product-content-heading {
    margin-bottom: 25px;
}

.uid-product-good-to-know .uid-good-to-know-items {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 30px;
}

.uid-product-good-to-know .uid-good-to-know__content {
    width: calc((100% - 30px * (min(3, var(--item-number, 3)) - 1)) / min(3, var(--item-number, 3)));
    display: flex;
    gap: 20px;
    position: relative;
}

.uid-product-good-to-know .uid-good-to-know__content-image {
    border-radius: 20px;
    overflow: hidden;
    width: 75%;
    border: 2px solid var(--core-text-primary);
    height: fit-content;
}

.uid-product-good-to-know .uid-good-to-know__content-image img {
    aspect-ratio: 1 / 1;
}

.uid-product-good-to-know .uid-good-to-know__content-paragh {
    width: 100%;
    display: flex;
    flex-direction: column;
}

.uid-good-to-know-check-image {
    position: absolute;
    width: 12%;
    z-index: 10;
    top: -10%;
    left: -5%;

}



/* FAQs  */


.uid-product-content-faqs .uid-product-content-heading {
    margin-bottom: 25px;
}

.uid-faqs-items {
    display: flex;
    flex-direction: column;
    gap: 12px;
}
.uid-faqs-question {
    font-size: 18px;
    font-weight: 500;
    line-height: 1.4;
    color: var(--core-text-primary);
    cursor: pointer;
    padding: 12px 15px;
    background-color: var(--core-color-bg);
    border-radius: 10px;
    border: solid 1px var(--core-color-border);
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0;
}
.uid-faqs-icon {
    position: relative;
    width: 16px;
    height: 16px;
}
.uid-faqs-icon::after, .uid-faqs-icon::before {
    position: absolute;
    content: "";
    background-color: #000000;
}
.uid-faqs-icon::after {
    width: 100%;
    height: 2px;
    top: 50%;
    left: 0;
    transform: translateY(-50%);
}
.uid-faqs-icon::before {
    height: 100%;
    width: 2px;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    transition: transform .3s ease;
}
.uid-faqs-answer {
    font-size: 16px;
    font-weight: 400;
    line-height: 1.6;
    color: var(--core-text-primary);
    display: none;
    padding: 0px 10px 10px 10px;
}
.product-tabs__radio:checked + .uid-faqs-question + .uid-faqs-answer {
    display: block;
}
.product-tabs__radio:checked + .uid-faqs-question > .uid-faqs-icon::before {
    transform: rotate(90deg);
}

@media only screen and (max-width: 798px) {
    .uid-product-content-wrapper {
        margin-top: 20px;
        margin-bottom: 35px;
    }
    .uid-product-content-container {
        gap: 20px;
    }
    /* Benefit  */
    .uid-product-content__benefits {
        --layout-padding-left-right: 0px;
    }

    .uid-product-content__benefits .uid-benefits__cols-wrapper {
        --gap: 15px;
        --columns: 1;
        overflow-x: scroll;
        flex-wrap: nowrap;
    }
    .uid-product-content__benefits .uid-benefits__cols-wrapper::-webkit-scrollbar {
        width: 0px;
        height: 0px;
    }

    .uid-product-content__benefits .uid-benefits__content {
        padding-bottom: 10px;
        flex: 0 0 67%;

    }

    .uid-product-content-heading {
        font-size: 24px;
    }

    .uid-product-content-title {
        font-size: 18px;
        letter-spacing: -2%;
    }


    .uid-product-content-desc {
        font-size: 15px;
    }



    /* Details  */

    .uid-product-content__details {
        flex-wrap: wrap;
    }

    .uid-details-content-item .uid-details-content-image {
        width: 50%;
    }
    .uid-product-content__details .uid-details-image{
        flex: 100%;
    }
    /* Occasions  */

    .uid-product-occasions .uid-occasions-video {
        width: 100%;
    }

    .uid-product-occasions .uid-occasions-image {
        display: none;
    }

    .uid-product-occasions .uid-occasions-items {
        gap: 15px;
    }

    .uid-product-occasions .uid-occasions__content {
        width: calc(100% / 2 - 15px / 2);
        padding: 10px 10px 15px 10px;
    }

    .uid-product-occasions .uid-occasions__content-image {
        width: 40%;
    }



    /* Good to know  */

    .uid-product-good-to-know {
        padding-left: 12px;
    }

    .uid-product-good-to-know .uid-good-to-know-items {
        gap: 20px;
    }

    .uid-product-good-to-know .uid-good-to-know__content {
        width: 100%;
        gap: 15px;
    }

    .uid-product-good-to-know .uid-good-to-know__content-image {
        width: 60%;
    }

    .uid-good-to-know-check-image {
        width: 10%;
        left: -4%;
    }


    /* FAQs  */

    .uid-product-content-faqs .uid-product-content-heading {
        margin-bottom: 15px;
    }
    .uid-faqs-question {
        font-size: 16px;
    }
    .uid-faqs-answer {
        font-size: 15px;
    }
}
